from itertools import product
from pathlib import Path

# Boilerplate code generated by OVITO Pro 3.15.5
from ovito.io import import_file
from ovito.vis import Viewport, ColorLegendOverlay
from ovito.qt_compat import QtCore


METALS: list[str] = ["W", "Mo", "Ta"]
CHALCOGEN_PAIRS: list[tuple[str, str]] = [("S", "Te"), ("Se", "Te")]
TEMPERATURES: list[int] = [100, 400]


def main():

    for temperature, metal, pair in product(TEMPERATURES, METALS, CHALCOGEN_PAIRS):

        path = Path("mc-data") / f"{metal}{''.join(pair)}" / f"{temperature:0d}"

        # Data import:
        pipeline1 = import_file(path / "frame_99.xyz")
        pipeline1.compute().cell.vis.enabled = False

        # ======= Set up visual elements ======= #

        # Add pipelines to visualization scene
        pipeline1.add_to_scene()

        # ========== Set up rendering ========== #

        # Viewport setup:
        
        vp = Viewport(
            type = Viewport.Type.Perspective, 
            fov = 0.610865238198, 
            camera_dir = [-0.49923017660270624, 0.665640235470275, -0.5547001962252291], 
            camera_pos = [57.65553192379811, -40.09640241334773, 62.53445943277541], 
            camera_up = [-0.33282011773513753, 0.4437601569801834, 0.8320502943378438])
        vp.overlays.append(ColorLegendOverlay(
            alignment = QtCore.Qt.AlignmentFlag.AlignTrailing | QtCore.Qt.AlignmentFlag.AlignBottom, 
            offset_x = -0.0902, 
            offset_y = 0.8398, 
            legend_size = 0.275, 
            font_size = 0.35, 
            label_size = 0.5, 
            title = ' ', 
            property = "particles/Particle Type", 
            border_enabled = True))

        new_path = Path("figures") / "renderings" / f"{metal}{''.join(pair)}"
        new_path.mkdir(exist_ok=True, parents=True)

        # Rendering:
        vp.render_image(filename=str(new_path / f"{temperature:0d}.png"), size=(1000, 1000), frame=99)
        pipeline1.remove_from_scene()
        del vp


if __name__ == "__main__":

    main()
